Method.Implementation:
#dim tSC As %Status=$$$OK $$$TRACE("Inside Method ProcessHttpsRequest") set URL = ..Adapter.URL $$$TRACE("EndPoint URL: "_URL)
Set httprequest=##class(%Net.HttpRequest).%New() Set httprequest.ContentType="text/plain" Set httprequest.Https="1" Set httprequest.SSLConfiguration = ..Adapter.SSLConfig Set httprequest.Location = ..Adapter.URL
Set pResponse = ##class(Ens.StringResponse).%New()
try{ //Do httprequest.EntityBody.Write(dupId) ;
$$$TRACE("Calling Cern Drc drt-getreportdate Service.....")
set postStatus = httprequest.Post(URL) set postStatusTxt = $SYSTEM.Status.GetOneErrorText(postStatus) $$$TRACE("postStatusTxt--> "_postStatusTxt) set response=httprequest.HttpResponse $$$TRACE("StatusLine: "_response.StatusLine)
if (postStatus =1){ $$$TRACE(" Cerner Drc drt-getreportdate call success!!!") set len = httprequest.HttpResponse.ContentLength set respData = httprequest.HttpResponse.Data.Read() $$$TRACE("Last Run Report Date in Cerner: "_respData) Set pResponse.StringValue = respData }
}catch e{ set errTxt = $System.Status.GetErrorText("Unknown Exception while calling Cerner Drc drt-getreportdate call "_e) $$$TRACE(" Unknown Exception: " _ errTxt) Set tSC = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError("Op-Cern-Demogr-Json-LASTRUNDRCREPORTDATE",errTxt) } quit tSC
